import React, {useState} from "react";
import "../static/css/login.css";
import {Link} from "react-router-dom";

function Login() {
    const [formData, setFormData] = useState({
        email: "",
        password: "",
    });
    const [errors, setErrors] = useState({});
    const [successMessage, setSuccessMessage] = useState("");
    const [tokenPopup, setTokenPopup] = useState(false);
    const [token, setToken] = useState("");
    const [email, setEmail] = useState("");

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData((prev) => ({ ...prev, [name]: value }));
        console.log("handle input change");
    };

    const validateForm = () => {
        const newErrors = {};

        if (!formData.email.trim()) {
            newErrors.email = "L'email est obligatoire.";
        }

        if (!formData.password.trim()) {
            newErrors.password = "Le mot de passe est obligatoire.";
        }

        console.log("validating form");
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleLogin = async (e) => {
        e.preventDefault();
        if (!validateForm()) return;

        try {
            const response = await fetch("/api/users/login", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify(formData),
            });

            console.log("Done")
            const data = await response.text();
            if (response.ok) {
                setSuccessMessage("Connexion réussie !");
                setEmail(formData.email);
                setTokenPopup(true);
                setErrors({});
            } else {
                setErrors({ apiError: data });
            }
        } catch (error) {
            setErrors({ apiError: "Erreur de connexion au serveur." });
        }
    };

    const handleVerifyToken = async () => {

        try {
            const response = await fetch("/api/users/verify-token", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({ email, token }),
            });

            const data = await response.text();
            console.log("done")
            if (response.ok) {
                const parsedData = JSON.parse(data);
                alert("Token vérifié avec succès !");
                localStorage.setItem("authToken", parsedData.token);
                localStorage.setItem("id", parsedData.id);
                localStorage.setItem("username", parsedData.username);
                localStorage.setItem("email", parsedData.email);
                window.location.href = `/Dashboard/${parsedData.id}`;
            } else {
                alert(data);
            }
        } catch (error) {
            console.log("erreur")
            alert("Erreur de connexion au serveur.");
        }
    };

    return (
        <div className="login-container">
            <header className="login-header">
                <h1>La cryptomonnaie de l'avenir</h1>
                <Link to="/" className="header-btn-accueil">Accueil</Link>
                <button className="header-btn-register" onClick={() => (window.location.href = "/Register")}>
                    S'inscrire
                </button>
            </header>
            <form className="login-form" onSubmit={handleLogin}>
                <h2>Connexion</h2>

                <label>
                    <p>Email :</p>
                    <input
                        type="email"
                        name="email"
                        value={formData.email}
                        onChange={handleInputChange}
                    />
                </label>
                {errors.email && <p className="error">{errors.email}</p>}

                <label>
                    <p>Mot de passe :</p>
                    <input
                        type="password"
                        name="password"
                        value={formData.password}
                        onChange={handleInputChange}
                    />
                </label>
                {errors.password && <p className="error">{errors.password}</p>}

                {errors.apiError && <p className="error">{errors.apiError}</p>}

                <p className="register-link">Mot de passe oublie ? {" "}
                    <a href="/ForgotPassword">Cliquez ici</a>
                </p>

                <button type="submit" className="login-btn-connect">Se connecter</button>
                <p className="register-link">
                    Vous n'avez pas de compte ?{" "}
                    <a href="/Register">Inscrivez-vous ici</a>
                </p>

                {successMessage && <p className="success">{successMessage}</p>}
            </form>

            {tokenPopup && (
                <div className="token-popup">
                    <h2>Entrez votre token</h2>
                    <input
                        type="text"
                        placeholder="Token"
                        value={token}
                        onChange={(e) => setToken(e.target.value)}
                    />
                    <button onClick={handleVerifyToken}>Vérifier</button>
                </div>
            )}
        </div>
    );
}

export default Login;
